 reportpath=ROOT/'validation/campaign/chapter06_predefined_consumer_final_v3/verification.json';r=json.loads(reportpath.read_bytes());assert r['passed'] and r['actual_exit']==0 and r['source_before']==r['source_after'];assert all(sha(Path(p))==h for p,h in r['source_after'].items());module=ROOT/'packages/campaign/chapter06_predefines_consumer/module.v2.reference.json';assert sha(module)==r['actual_module_sha'];source=module.parent/'source.profile.json';profile=json.loads(source.read_bytes());assert profile['source_before']==profile['source_after'] and all(sha(Path(p))==h for p,h in profile['source_after'].items());evidence=reportpath.parent;trace=json.loads((evidence/'actual_source_trace.json').read_bytes());cp=evidence/'actual_midcast.cp.json';assert sha(cp)==trace['checkpoint_sha'];assert trace['areas'][0]['time']-trace['casts'][0]['time']==25
