 result={'role':'Source-operated frost trap author candidate; independent peer and Boss actual trigger integration pending','core':r['core'],'module':{'path':str(module),'sha':sha(module)},'source_profile':{'path':str(source),'sha':sha(source)},'source_before':r['source_before'],'source_after':r['source_after'],'author':{'actual_exit':0,'checks':7,'elapsed':r['elapsed_seconds'],'report':str(reportpath),'sha':sha(reportpath)},'actual_evidence':[{ 'path':str(p),'sha':sha(p),'bytes':p.stat().st_size} for p in evidence.glob('*') if p.is_file()],'source_archives':archives,'actual_native_source_model':{'HP':100,'ATK':0,'SPcost':15,'SPinitial':0,'SPtimeRecovery':1,'native_predelay_seconds':profile['model_policies']['frame_quantization']['source_seconds'],'actual_predelay_ticks':25,'first_activation_at':100,'first_cast_at':trace['casts'][0]['time'],'first_Cold_area_at':trace['areas'][0]['time'],'range_cells':13,'Coldseconds':10,'two_sameframe_sources_cold_to_frozen_passed':True,'dormant_then_sameinstance_activation':True,'actual_midcast_CP_sourceSHAload_resume_publichead_equal':True,'true_owned_terrain_layer_release':True,'source_no_damage':True},'reference_policy_limits':profile['model_policies'],'missing_native_body_policy_explicit':True,'old_author_failures_preserved':True,'independent_review_passed':False,'actual_boss_trigger_join_verified':False,'whole_stage_executed':False,'runtime_modified':False,'primary_promotion':False,'client_verified':False};dest=OUT/'freeze.json';dest.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='');print(json.dumps({'sha':sha(dest),'module_sha':sha(module),'author7_actual_exit':0,'independent_pending':True}))
